import z3

# Verify the graph
edges = [(0, 15), (0, 16), (1, 2), (1, 6), (2, 5), (2, 7), (2, 10), (3, 7), (3, 13), (3, 18), (4, 5), (4, 6), (4, 12), (4, 13), (4, 15), (6, 14), (7, 16), (8, 11), (8, 13), (8, 14), (8, 16), (9, 15), (9, 17), (9, 18), (10, 11), (10, 12), (10, 17), (11, 15), (12, 16), (12, 18), (13, 17), (14, 18)]

# Build adjacency list
adj = [[] for _ in range(19)]
for u, v in edges:
    adj[u].append(v)
    adj[v].append(u)

# Check triangle-free
has_triangle = False
for i in range(19):
    for j in range(i+1, 19):
        if j not in adj[i]:
            continue
        for k in range(j+1, 19):
            if k in adj[i] and k in adj[j]:
                has_triangle = True
                print(f"Triangle: {i}-{j}-{k}")

print(f"Triangle-free: {not has_triangle}")

# Check 4-cycle-free
has_4cycle = False
for i in range(19):
    for j in range(i+1, 19):
        if j not in adj[i]:
            continue
        for k in range(19):
            if k == i or k == j:
                continue
            if k not in adj[j]:
                continue
            for l in range(k+1, 19):
                if l == i or l == j or l == k:
                    continue
                if l in adj[k] and l in adj[i]:
                    has_4cycle = True
                    print(f"4-cycle: {i}-{j}-{k}-{l}")

print(f"4-cycle-free: {not has_4cycle}")

# Check 5-colorable
# Find a 5-coloring via Z3
s = z3.Solver()
colors = [z3.Int(f"c_{i}") for i in range(19)]
for i in range(19):
    s.add(colors[i] >= 0, colors[i] < 5)
for u, v in edges:
    s.add(colors[u] != colors[v])
r = s.check()
print(f"5-colorable: {r == z3.sat}")
if r == z3.sat:
    m = s.model()
    col = [m.evaluate(colors[i]).as_long() for i in range(19)]
    print("Coloring:", col)

# Count edges
print(f"Number of edges: {len(edges)}")
